              )



            AND E.ID in (select EVAID from TBL_YQNS_NDTB_GL where TBID= #{queryParam.tbid} )





            AND E.CREATETIME >= #{queryParam.startyear}



           AND E.CREATETIME <=  #{queryParam.endyear } 


		  order by  projectType,sortNumber desc

